package migration
import("testing";"math/big";"path/filepath";"fmt";"crypto/sha256";"os";"encoding/json";"github.com/ethereum/go-ethereum/common";"github.com/ethereum/go-ethereum/crypto";"github.com/holiman/uint256")
func TestMetadataReviewBoundary(t *testing.T){
 for _, length := range []uint64{31,32,1<<20,(1<<20)+1}{
  f:=newFixtureWithStorage(t,0,0,func(storage map[common.Hash]common.Hash){
   for _, n:=range []byte{3,4}{
    var slot,word common.Hash;slot[31]=n
    if length<32{word[0]='x';word[31]=byte(length*2)}else{
     v:=new(big.Int).SetUint64(length);word=common.BigToHash(v.Add(v.Lsh(v,1),big.NewInt(1)))
     for _,off:=range []uint64{0,(length-1)/32}{b:=new(uint256.Int).SetBytes(crypto.Keccak256(slot[:]));k:=b.Add(b,uint256.NewInt(off)).Bytes32();storage[crypto.Keccak256Hash(k[:])]=common.HexToHash("0x03")}
    };storage[crypto.Keccak256Hash(slot[:])]=word
   }
  })
  before:=filesDigest(t,f.source)
  for _,codec:=range []string{"none","zstd"}{for _,cache:=range []string{"memory","none"}{for _,workers:=range []int{2,16}{for _,command:=range []string{"migrate","dump"}{
   path:=filepath.Join(t.TempDir(),"state");var result Result;var err error
   if command=="migrate"{o:=f.options(path);o.Compression=codec;o.CodeCache=cache;o.Workers=workers;result,err=Migrate(t.Context(),o)}else{o:=dumpOptions(f,path);o.Compression=codec;o.CodeCache=cache;o.Workers=workers;result,err=Dump(t.Context(),o)}
   must(t,err);_,_,verified:=readArtifact(t,path);if verified!=result.Summary{t.Fatal("verification mismatch")};b,err:=os.ReadFile(path);must(t,err)
   row:=map[string]any{"case":fmt.Sprintf("%d/%s/%s/%d/%s",length,codec,cache,workers,command),"sha256":fmt.Sprintf("%x",sha256.Sum256(b)),"summary":result.Summary};data,err:=json.Marshal(row);must(t,err);t.Logf("BOUNDARY %s",data)
  }}}}
  if before!=filesDigest(t,f.source){t.Fatal("source changed")}
 }
}
